{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h1",
        "intro_text",
        "menu_section_stack",
        "shopping_section_stack",
        "timeline_section_stack",
        "actions_section_stack",
        "sources_section_stack"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Mediterranean Sunday Brunch Plan",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "A comprehensive guide for hosting a 6-adult Mediterranean brunch in London, featuring vibrant flavors and synchronized preparation.",
        "variant": "body"
      },
      "children": []
    },
    "menu_section_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "menu_image",
        "menu_header_stack",
        "menu_table"
      ]
    },
    "menu_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2d/Shakshuka_Stoves_and_Graze.jpg/1200px-Shakshuka_Stoves_and_Graze.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "menu_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "menu_icon",
        "menu_title_h2"
      ]
    },
    "menu_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/cup-hot.svg"
      },
      "children": []
    },
    "menu_title_h2": {
      "type": "Text",
      "props": {
        "text": "Mediterranean Brunch Menu",
        "variant": "h2"
      },
      "children": []
    },
    "menu_table": {
      "type": "Table",
      "props": {
        "columns": [
          { "key": "item", "label": "Item" },
          { "key": "description", "label": "Description" },
          { "key": "notes", "label": "Notes" }
        ],
        "rows": [
          {
            "item": "Spicy Shakshuka",
            "description": "8 eggs poached in a sauce of 800g tomatoes, 2 peppers, 1 onion, 4 garlic cloves, and 2 tsp harissa. Served with 1 large sourdough loaf.",
            "notes": ""
          },
          {
            "item": "Spinach & Feta Filo Pie",
            "description": "500g spinach, 250g feta, 3 eggs, and 1 pack filo pastry.",
            "notes": "Gluten-Free Mod: Prepare a crustless version in a separate ramekin using GF breadcrumbs or a GF puff pastry base for the specific guest."
          },
          {
            "item": "Greek Yogurt Parfait Station",
            "description": "1kg Greek yogurt, 150ml honey, 150g toasted walnuts, and 300g seasonal berries.",
            "notes": ""
          }
        ],
        "domain": "generic",
        "preferredPresentation": "cards",
        "primaryColumn": "item"
      },
      "children": []
    },
    "shopping_section_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "shopping_header_stack",
        "shopping_table"
      ]
    },
    "shopping_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "shopping_icon",
        "shopping_title_h2"
      ]
    },
    "shopping_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/currency-pound.svg"
      },
      "children": []
    },
    "shopping_title_h2": {
      "type": "Text",
      "props": {
        "text": "Shopping List & Budget (London, UK)",
        "variant": "h2"
      },
      "children": []
    },
    "shopping_table": {
      "type": "Table",
      "props": {
        "columns": [
          { "key": "category", "label": "Category" },
          { "key": "items", "label": "Items" },
          { "key": "cost", "label": "Cost" }
        ],
        "rows": [
          { "category": "Produce", "items": "Spinach, Peppers/Onion/Garlic, Berries", "cost": "£9.50" },
          { "category": "Dairy/Eggs", "items": "12 Eggs, Feta, Greek Yogurt, Butter", "cost": "£12.50" },
          { "category": "Pantry/Bakery", "items": "Sourdough, Filo/GF Pastry, Harissa/Honey/Walnuts", "cost": "£13.50" },
          { "category": "Estimated Total Cost", "items": "Total", "cost": "£35.50 (£5.92 per person)" }
        ],
        "domain": "generic",
        "preferredPresentation": "table",
        "numericColumns": ["cost"]
      },
      "children": []
    },
    "timeline_section_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "timeline_header_stack",
        "timeline_table"
      ]
    },
    "timeline_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "timeline_icon",
        "timeline_title_h2"
      ]
    },
    "timeline_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/clock.svg"
      },
      "children": []
    },
    "timeline_title_h2": {
      "type": "Text",
      "props": {
        "text": "Preparation Timeline",
        "variant": "h2"
      },
      "children": []
    },
    "timeline_table": {
      "type": "Table",
      "props": {
        "columns": [
          { "key": "time", "label": "Time" },
          { "key": "activity", "label": "Activity" }
        ],
        "rows": [
          { "time": "09:00 - 09:30", "activity": "Prep vegetables; wilt and drain spinach thoroughly for the pie." },
          { "time": "09:30 - 10:15", "activity": "Assemble Filo Pie and GF modification; set aside in fridge." },
          { "time": "10:15 - 11:00", "activity": "Prepare Parfait station components; toast walnuts; slice sourdough." },
          { "time": "11:00 - 11:30", "activity": "Bake Filo Pies (200°C); start Shakshuka base sauce on stovetop." },
          { "time": "11:40 - 12:00", "activity": "Poach eggs in Shakshuka; warm sourdough; serve all dishes at 12:00." }
        ],
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "time",
        "highlightColumns": ["activity"]
      },
      "children": []
    },
    "actions_section_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "actions_title_h2",
        "grocery_button",
        "recipes_button"
      ]
    },
    "actions_title_h2": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "grocery_button": {
      "type": "Button",
      "props": {
        "label": "Local Grocery Delivery"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.tesco.com"
          }
        }
      },
      "children": []
    },
    "recipes_button": {
      "type": "Button",
      "props": {
        "label": "Mediterranean Recipes"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.bbcgoodfood.com/recipes/collection/mediterranean-recipes"
          }
        }
      },
      "children": []
    },
    "sources_section_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "sources_title_h2",
        "ons_button",
        "bbc_source_button"
      ]
    },
    "sources_title_h2": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "ons_button": {
      "type": "Button",
      "props": {
        "label": "ONS Retail Price Index"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.ons.gov.uk/economy/inflationandpriceindices"
          }
        }
      },
      "children": []
    },
    "bbc_source_button": {
      "type": "Button",
      "props": {
        "label": "BBC Good Food"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.bbcgoodfood.com"
          }
        }
      },
      "children": []
    }
  }
}
